#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Al-othmany Sender 3.5.2 - MERGED UPDATE

ONE real source update that merges:
1) Shizuku Continuity Hotfix from 3.5.1
2) Exact Real Dashboard UI from 3.5.2

Base accepted: 3.5.0 or a locally hotfixed 3.5.1.
Final version: 3.5.2 / versionCode 352.

This modifies the actual Android Kotlin/XML/resources. It does not generate
or place a screenshot inside the app.
"""

from pathlib import Path
import base64
import os
import sys
import traceback

ROOT = Path.cwd()
if not (ROOT / "app").is_dir():
    raise SystemExit("ERROR: run from /workspaces/AL-thmany-2.8.0")

HOTFIX_B64 = ''
UI_B64 = ''

def run_embedded(label: str, payload_b64: str) -> None:
    print()
    print("=" * 68)
    print(label)
    print("=" * 68)
    source = base64.b64decode(payload_b64).decode("utf-8")
    namespace = {
        "__name__": "__main__",
        "__file__": f"<embedded:{label}>",
    }
    try:
        exec(compile(source, namespace["__file__"], "exec"), namespace, namespace)
    except SystemExit:
        raise
    except Exception:
        traceback.print_exc()
        raise SystemExit(f"ERROR while applying: {label}")

# Step 1 is intentionally idempotent. If 3.5.1 hotfix is already present,
# it only verifies/finishes missing pieces.
run_embedded(
    "STEP 1/2 - APPLY SHIZUKU CONTINUITY + FALSE-PAUSE HOTFIX",
    HOTFIX_B64,
)

# Step 2 upgrades the real visible Android UI and final version to 3.5.2.
run_embedded(
    "STEP 2/2 - APPLY EXACT REAL DASHBOARD UI",
    UI_B64,
)

build_gradle = (ROOT / "app/build.gradle.kts").read_text(encoding="utf-8")
shizuku = (
    ROOT / "app/src/main/java/com/althmany/groupmanager/shizuku/"
    "ShizukuAutomationService.kt"
).read_text(encoding="utf-8")
layout = (ROOT / "app/src/main/res/layout/activity_main.xml").read_text(encoding="utf-8")
main_activity = (
    ROOT / "app/src/main/java/com/althmany/groupmanager/ui/MainActivity.kt"
).read_text(encoding="utf-8")

required = [
    ('versionCode = 352', build_gradle),
    ('versionName = "3.5.2"', build_gradle),
    ('SHIZUKU_CONTROLLED_EXIT_HANDOFF', shizuku),
    ('SHIZUKU_VISUAL_AMBIGUOUS_NO_BACK', shizuku),
    ('POST_ACTION_RESULT_GRACE_MS = 650L', shizuku),
    ('CONTROLLED_EXIT_HANDOFF_GRACE_MS = 1_500L', shizuku),
    ('exactDashboardRoot', layout),
    ('legacyDashboard', layout),
    ('exactShizukuStatus', layout),
    ('exactAccessibilityStatus', layout),
    ('exactStartButton', layout),
    ('exactLinksInput', layout),
    ('exactSpeedToggle', layout),
    ('exactPersonalButton', layout),
    ('exactBusinessButton', layout),
    ('exactDualButton', layout),
    ('exactProgress', layout),
    ('configureExactDashboard()', main_activity),
    ('syncExactDashboardStatus()', main_activity),
]

missing = [token for token, source in required if token not in source]
if missing:
    print("ERROR: merged sanity check failed:")
    for token in missing:
        print(" -", token)
    raise SystemExit(1)

print()
print("=" * 68)
print("✅ AL-OTHMANY SENDER 3.5.2 MERGED UPDATE APPLIED")
print("=" * 68)
print("Included:")
print(" - false user-exit pause fix")
print(" - controlled Back/X handoff")
print(" - no blind Back for ambiguous visual result")
print(" - UI dump cooldown failure-count correction")
print(" - 650ms post-action verification grace")
print(" - exact real dark/cyan dashboard UI")
print(" - hidden legacy bindings retained for engine compatibility")
print(" - final versionCode=352 / versionName=3.5.2")
print()
print("Next run:")
print("  python3 scripts/validate_source.py")
print("  git diff --check")
print("  gradle --no-daemon --no-configuration-cache :app:assembleDebug --console=plain")
